// DecodeError identifies and decodes a declared custom error.
func (c *IDiesisPerpDeployBinding) DecodeError(raw []byte) (any, error) {
	if len(raw) < 4 {
		return nil, fmt.Errorf("revert payload is shorter than a selector")
	}
	if definition, err := c.customError("DeadlineExceeded()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeDeadlineExceededError(raw)
	}
	if definition, err := c.customError("InvalidStateTransition()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeInvalidStateTransitionError(raw)
	}
	if definition, err := c.customError("NoSuchMarket()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeNoSuchMarketError(raw)
	}
	if definition, err := c.customError("PerpDeployCallFailed()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodePerpDeployCallFailedError(raw)
	}
	if definition, err := c.customError("WrongOperator()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeWrongOperatorError(raw)
	}
	return nil, fmt.Errorf("unknown custom error selector %x", raw[:4])
}
